    surpriseThreshold?: number;
  };
  partitioning?: {
    enabled?: boolean;
    retentionMonths?: number;
    createAheadMonths?: number;
    maintenanceIntervalMs?: number;
  };
};

export type EventTypes = string;

// ============================================================================
// Global Registry (Singleton)
// ============================================================================

export const globalEventMeshRegistry = new Map<string, AgentEventMesh>();

/**
 * Get or create global event mesh instance
 */
export function getEventMesh(config: EventMeshConfig): AgentEventMesh {
  const key = config.agentId;

  if (!globalEventMeshRegistry.has(key)) {
    const mesh = new AgentEventMesh(config);
    globalEventMeshRegistry.set(key, mesh);
  }

  return globalEventMeshRegistry.get(key)!;
}

/**
 * Get or create singleton event mesh
 */
export function getOrCreateEventMesh(config: EventMeshConfig): AgentEventMesh {
  return getEventMesh(config);
}

