```typescript
import { EventEmitter } from 'events';
import { spawn, ChildProcess } from 'child_process';
import Msgpack from 'msgpack-lite';
import { createConnection, Socket } from 'net';

export class NeuroMemoryClient extends EventEmitter {
  private socket: Socket | null = null;
  private pythonProcess: ChildProcess | null = null;
  private isConnected = false;
  private reconnectAttempts = 0;

  constructor(
    private config: {
      pythonScriptPath: string;
      socketPath: string;
      autoStart: boolean;
    }
  ) {
    super();
    if (config.autoStart) {
      this.start();
    }
  }

  async start(): Promise<void> {
    // Start Python process
    this.pythonProcess = spawn('python', [
      `${this.config.pythonScriptPath}/main.py`,
      '--socket', this.config.socketPath
    ], {
      stdio: ['ignore', 'pipe', 'pipe']
    });

    this.pythonProcess.stderr?.on('data', (data) => {
      console.error('[NeuroMemory]', data.toString());
    });

    // Wait for socket to be ready
    await this.waitForSocket();
  }

  private waitForSocket(): Promise<void> {
    return new Promise((resolve, reject) => {
      const maxAttempts = 50;
      const interval = setInterval(() => {
        this.socket = createConnection(this.config.socketPath);

        this.socket.once('connect', () => {
          clearInterval(interval);
          this.isConnected = true;
          this.reconnectAttempts = 0;
          resolve();
        });

        this.socket.once('error', () => {
          this.reconnectAttempts++;
          if (this.reconnectAttempts >= maxAttempts) {
            clearInterval(interval);
            reject(new Error('NeuroMemory failed to start'));
          }
        });
      }, 200);
    });
  }

  /**
   * Push event batch to neuro-memory (fire-and-forget)
   * Non-blocking - returns immediately
   */
  async pushBatch(events: any[]): Promise<void> {
    if (!this.isConnected || !this.socket) {
      // Silently drop if not connected (graceful degradation)
      return;
    }

    try {
      const payload = Msgpack.encode({
        type: 'batch',
        timestamp: Date.now(),
        events: events.map(e => ({
          type: e.type,
          timestamp: e.timestamp,
          data: e.data
        }))
      });

      // Write length prefix + payload (simple framing)
      const length = Buffer.alloc(4);
      length.writeUInt32BE(payload.length, 0);

      this.socket.write(Buffer.concat([length, payload]));
    } catch (err) {
      // Log but don't throw - neuro-memory is non-critical
      console.warn('[NeuroMemory] Push failed:', err);
    }
  }

  /**
   * Query neuro-memory for evolution insights
   * This is called during evolution runs (weekly, async)
   */
  async queryInsights(query: {
    type: 'failure_patterns' | 'surprise_events' | 'recommendations';
    timeRange?: { start: number; end: number };
    limit?: number;
  }): Promise<any[]> {
    return new Promise((resolve, reject) => {
      if (!this.isConnected || !this.socket) {
        resolve([]); // Graceful degradation
        return;
      }

      const requestPayload = Msgpack.encode({
        type: 'query',
        query: query
      });

      const length = Buffer.alloc(4);
      length.writeUInt32BE(requestPayload.length, 0);

      // Create one-time response handler
      const handler = (data: Buffer) => {
        try {
          const response = Msgpack.decode(data);
          this.socket?.off('data', handler);
          resolve(response.insights || []);
        } catch (err) {
          reject(err);
        }
      };

      this.socket.on('data', handler);
      this.socket.write(Buffer.concat([length, requestPayload]));

      // Timeout after 5s
      setTimeout(() => {
        this.socket?.off('data', handler);
        resolve([]);
      }, 5000);
    });
  }

  async stop(): Promise<void> {
    this.socket?.destroy();
    this.pythonProcess?.kill();
  }
}
```

