#!/usr/bin/env python3
import asyncio
import argparse
import struct
import msgpack
import os
from typing import List, Dict, Any
import sys

# Add neuro-memory-agent to path
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from neuro_memory import NeuroMemoryAgent, Event, EventType
from storage import SQLiteStorage

class NeuroMemoryServer:
    def __init__(self, socket_path: str):
        self.socket_path = socket_path
        self.agent = NeuroMemoryAgent()
        self.storage = SQLiteStorage('neuro_memory.db')
        self.running = False

    async def handle_client(self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter):
        """Handle incoming connection"""
        try:
            while self.running:
                # Read length prefix (4 bytes)
                length_data = await reader.readexactly(4)
                length = struct.unpack('>I', length_data)[0]

                # Read payload
                payload_data = await reader.readexactly(length)
                message = msgpack.unpackb(payload_data, raw=False)

                if message['type'] == 'batch':
                    await self.handle_batch(message['events'])
                elif message['type'] == 'query':
                    response = await self.handle_query(message['query'])
                    writer.write(msgpack.packb(response))
                    await writer.drain()

        except asyncio.IncompleteReadError:
            # Client disconnected
            pass
        except Exception as e:
            print(f"Error handling client: {e}", file=sys.stderr)
        finally:
            writer.close()

    async def handle_batch(self, events: List[Dict[str, Any]]):
        """Process batch of events through neuro-memory"""
        # Convert to neuro-memory Event objects
        neuro_events = []
        for e in events:
            event = Event(
                event_type=EventType(e['type']),
                timestamp=e['timestamp'],
                data=e['data']
            )
            neuro_events.append(event)

        # Process through neuro-memory agent
        # This computes Bayesian surprise, segmentation, etc.
        results = self.agent.process_batch(neuro_events)

        # Store results
        for event, result in zip(neuro_events, results):
            self.storage.store_event(
                event=event,
                surprise_score=result.surprise_score,
                segment_id=result.segment_id,
                embedding=result.embedding
            )

        # Periodic consolidation (every 1000 events or 6 hours)
        if self.storage.event_count() % 1000 == 0:
            await self.consolidate()

    async def consolidate(self):
        """Run consolidation (short-term → long-term)"""
        print("[NeuroMemory] Running consolidation...")
        self.agent.consolidate()
        self.storage.prune_old_memories(max_age_days=30)

    async def handle_query(self, query: Dict[str, Any]) -> Dict[str, Any]:
        """Query neuro-memory for insights"""
        query_type = query['type']

        if query_type == 'failure_patterns':
            patterns = self.storage.get_failure_patterns(
                time_range=query.get('timeRange'),
                limit=query.get('limit', 10)
            )
            return {'insights': patterns}

        elif query_type == 'surprise_events':
            events = self.storage.get_high_surprise_events(
                threshold=0.8,
                limit=query.get('limit', 20)
            )
            return {'insights': events}

        elif query_type == 'recommendations':
            # Use neuro-memory's learned patterns to generate recommendations
            recommendations = self.agent.generate_recommendations()
            return {'insights': recommendations}

        return {'insights': []}

    async def run(self):
        """Start the server"""
        # Remove old socket if exists
        if os.path.exists(self.socket_path):
            os.unlink(self.socket_path)

        self.running = True
        server = await asyncio.start_unix_server(
            self.handle_client,
            path=self.socket_path
        )

        # Make socket accessible
        os.chmod(self.socket_path, 0o666)

        print(f"[NeuroMemory] Listening on {self.socket_path}")

        async with server:
            await server.serve_forever()

    def stop(self):
        self.running = False

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--socket', default='/tmp/neuro-memory.sock')
    args = parser.parse_args()

    server = NeuroMemoryServer(args.socket)

    try:
        asyncio.run(server.run())
    except KeyboardInterrupt:
        server.stop()
