import { getNeuroMemory } from '../neuro-memory';

export class EvolutionService {
  async runEvolution(): Promise<EvolutionResult> {
    // 1. Query neuro-memory for insights
    const neuroMemory = getNeuroMemory();
    let insights: any[] = [];

    if (neuroMemory) {
      // Get failure patterns from last 7 days
      const failures = await neuroMemory.queryInsights({
        type: 'failure_patterns',
        timeRange: {
          start: Date.now() - 7 * 24 * 60 * 60 * 1000,
          end: Date.now()
        },
        limit: 20
      });

      // Get high-surprise events (might indicate edge cases)
      const surprises = await neuroMemory.queryInsights({
        type: 'surprise_events',
        limit: 10
      });

      insights = [...failures, ...surprises];
    }

    // 2. Generate proposals with neuro-memory context
    const proposals = await this.generateProposals(insights);

    // 3. Record evolution run as event (for future learning)
    await this.eventEmitter.emit('evolution_run', {
      proposalCount: proposals.length,
      insights: insights.length,
      timestamp: Date.now()
    });

    return { proposals, insights };
  }

  private async generateProposals(insights: any[]): Promise<Proposal[]> {
    // Use insights to generate smarter proposals
    // Example: "Avoid retries when timeout < 5s (learned from 12 failures)"
    const proposals: Proposal[] = [];

    for (const insight of insights) {
      if (insight.pattern_type === 'tool_failure') {
        proposals.push({
          type: 'constraint',
          description: `Avoid ${insight.context.tool} when ${insight.context.condition}`,
          confidence: insight.frequency / 100,
          evidence: `Learned from ${insight.frequency} failures`
        });
      }
    }

    // Also run traditional template-based proposals
    const templateProposals = await this.runTemplates();
    proposals.push(...templateProposals);

    return proposals;
  }
}
