  }

  /**
   * Called by evolution service when it's time to generate proposals.
   * Spawns Python process, waits for insights.
   * Timeout: 60 seconds (plenty for weekly run)
   */
  async computeInsights(
    options: {
      daysLookback?: number;
      focusArea?: 'failures' | 'all' | 'surprises';
    } = {}
  ): Promise<NeuroMemoryInsights | null> {
    const daysLookback = options.daysLookback || 30;
    const focusArea = options.focusArea || 'failures';

    return new Promise((resolve) => {
      const args = [
        path.join(this.pythonPath, 'analyze_for_evolution.py'),
        '--event-store', this.eventStorePath,
        '--days', String(daysLookback),
        '--focus', focusArea,
        '--output', 'json'
      ];

      const python = spawn('python3', args, {
        cwd: this.pythonPath,
        timeout: 60000 // 60s timeout
      });

      let stdout = '';
      let stderr = '';

      python.stdout.on('data', (data) => {
        stdout += data.toString();
      });

      python.stderr.on('data', (data) => {
        stderr += data.toString();
      });

      python.on('close', (code) => {
        if (code !== 0) {
          console.error('[NeuroMemory] Python exited with code', code);
          console.error('[NeuroMemory] stderr:', stderr);
          resolve(null); // Graceful degradation
          return;
        }

        try {
          const insights = JSON.parse(stdout) as NeuroMemoryInsights;
          console.log('[NeuroMemory] Computed insights:', {
            failurePatterns: insights.failurePatterns.length,
            surprises: insights.surprisingEvents.length,
            recommendations: insights.recommendations.length
