import { appendFile, readFile } from 'fs/promises';
import { existsSync } from 'fs';

interface StoredEvent {
  id: string;
  timestamp: string;
  type: string;
  data: any;
  metadata?: {
    toolName?: string;
    success?: boolean;
    durationMs?: number;
    error?: string;
  };
}

/**
 * Simple JSONL-based event store.
 * Hot path: append-only (fast).
 * Cold path: read all for analysis (batch).
 */
export class EventPersistence {
  private filePath: string;
  private writeBuffer: StoredEvent[] = [];
  private flushInterval: NodeJS.Timeout | null = null;

  constructor(filePath: string) {
    this.filePath = filePath;
    this.startFlushInterval();
  }

  /**
   * HOT PATH - called from event emit.
   * Just buffers in memory, flushes periodically.
   */
  store(event: StoredEvent): void {
    this.writeBuffer.push(event);

    // Flush if buffer is large
    if (this.writeBuffer.length >= 10) {
      this.flush();
    }
  }

  private startFlushInterval(): void {
    this.flushInterval = setInterval(() => {
      this.flush();
    }, 2000); // 2 seconds
  }

  private async flush(): Promise<void> {
    if (this.writeBuffer.length === 0) return;

    const events = [...this.writeBuffer];
    this.writeBuffer = [];

    const lines = events.map(e => JSON.stringify(e)).join('\n') + '\n';

    try {
      await appendFile(this.filePath, lines);
    } catch (err) {
      console.error('[EventPersistence] Failed to flush:', err);
      // Re-add to front of buffer to retry
      this.writeBuffer = [...events, ...this.writeBuffer];
    }
  }

  /**
   * COLD PATH - called by neuro-memory (via Python).
   * Reads all events from last N days.
   */
  async getRecentEvents(days: number): Promise<StoredEvent[]> {
    if (!existsSync(this.filePath)) {
      return [];
    }

    const content = await readFile(this.filePath, 'utf-8');
    const lines = content.trim().split('\n');

    const cutoff = Date.now() - (days * 24 * 60 * 60 * 1000);

    return lines
      .map(line => JSON.parse(line) as StoredEvent)
      .filter(e => new Date(e.timestamp).getTime() > cutoff);
  }

  stop(): void {
    if (this.flushInterval) {
      clearInterval(this.flushInterval);
    }
  }
}
