// src/services/evolution.ts

export class EvolutionService {
  private neuroMemory: NeuroMemoryBridge;

  async runEvolution(): Promise<void> {
    // 1. Get neuro-memory insights (cold path, can take seconds)
    const insights = await this.neuroMemory.computeInsights({
      daysLookback: 30,
      focusArea: 'failures'
    });

    // 2. Generate proposals with context
    const proposals: Proposal[] = [];

    if (insights) {
      // Use failure patterns to avoid known bad patterns
      for (const pattern of insights.failurePatterns) {
        if (pattern.frequency > 3) {
          proposals.push({
            type: 'avoid_pattern',
            description: `Avoid ${pattern.pattern} - failed ${pattern.frequency} times`,
            confidence: Math.min(0.9, pattern.frequency * 0.15),
            evidence: pattern.similarPastFailures
          });
        }
      }

      // Use recommendations
      for (const rec of insights.recommendations) {
        if (rec.confidence > 0.7) {
          proposals.push({
