// event-logger.ts - THE ENTIRE INTEGRATION LAYER
import { appendFile, mkdir } from 'fs/promises';
import { existsSync } from 'fs';

const EVENTS_DIR = '/var/openclaw/neuro-memory/events';
const CURRENT_LOG = `${EVENTS_DIR}/current.jsonl`;

export async function logEvent(event: NeuroEvent): Promise<void> {
  // Ensure directory exists
  if (!existsSync(EVENTS_DIR)) {
    await mkdir(EVENTS_DIR, { recursive: true });
  }

  // Single file append - that's it
  await appendFile(
