import { spawn } from 'child_process';
import { rotateEventsForEvolution } from './event-logger';

export async function runNeuroMemoryLearning(eventsPath: string): Promise<LearningResult> {
  return new Promise((resolve, reject) => {
    const python = spawn('python', [
      '-m', 'neuro_memory',
      '--events', eventsPath,
      '--mode', 'consolidate',
      '--output', 'json'  // Return insights for evolution
    ], {
      cwd: '/opt/openclaw/neuro-memory',
      env: { ...process.env, PYTHONUNBUFFERED: '1' }
    });

    let stdout = '';
    let stderr = '';

    python.stdout.on('data', (data) => { stdout += data; });
    python.stderr.on('data', (data) => { stderr += data; });

    python.on('close', (code) => {
      if (code === 0) {
        try {
          resolve(JSON.parse(stdout));
        } catch (e) {
          reject(new Error(`Invalid JSON output: ${stdout}`));
        }
      } else {
        reject(new Error(`Python exited ${code}: ${stderr}`));
      }
    });

    python.on('error', reject);
  });
}

// Called by evolution service weekly
export async function evolutionWithNeuroMemory(): Promise<void> {
  // 1. Rotate events file
  const eventsPath = await rotateEventsForEvolution();

