  await evolutionProposer.addContext({
    recentPatterns: insights.patterns,
    surprisingEvents: insights.bayesianSurprises,
    consolidatedMemories: insights.memories
  });

  // 4. Evolution continues as normal
  await evolutionProposer.run();
}
