  if (rec.confidence >= 0.70) {
    switch (rec.type) {
      case "avoid":
        evolution.addHardConstraint(rec.description, rec.confidence);
        break;
      case "prefer":
        evolution.addObjective(rec.description, rec.confidence);
        break;
      case "optimize":
        evolution.addOptimizationTarget(rec.description, rec.confidence);
        break;
      case "investigate":
        evolution.addExplorationTopic(rec.description);
        break;
      case "caution":
        evolution.addSoftConstraint(rec.description, rec.confidence * 0.5);
        break;
    }
  }
}
```

### `metadata.dataQuality`
```javascript
