/**
 * Query neuro-memory for evolution insights
 * This is the PRIMARY method called by evolution service
 * 
 * Returns insights about failures, successes, surprises, and recommendations
 * for smarter proposal generation.
 */
async queryInsights(query?: import("../types/neuro-memory-insights.js").EvolutionQuery): Promise<import("../types/neuro-memory-insights.js").NeuroMemoryInsights> {
  this.ensureReady();

  const startTime = Date.now();
  log.debug("[Evolution] Querying neuro-memory for insights...");

  try {
    const result = await this.request("query_insights", query || {});

    const duration = Date.now() - startTime;
    log.info(
      `[Evolution] Retrieved insights in ${duration}ms: ` +
      `${result.failurePatterns?.length || 0} failures, ` +
      `${result.successPatterns?.length || 0} successes, ` +
      `${result.recommendations?.length || 0} recommendations`
    );

    return result;
  } catch (error) {
    const msg = error instanceof Error ? error.message : String(error);
    log.error(`[Evolution] Failed to query insights: ${msg}`);

    // Return fallback insights (will trigger template-based evolution)
    return this.getFallbackInsights(msg);
  }
}

/**
 * Get fallback insights when neuro-memory is unavailable
 * This ensures evolution can still run with template-based proposals
 */
private getFallbackInsights(reason: string): import("../types/neuro-memory-insights.js").NeuroMemoryInsights {
  log.warn(`[Evolution] Using fallback insights (reason: ${reason})`);

  return {
    metadata: {
      period: {
        start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
        end: new Date().toISOString().split('T')[0],
      },
      generatedAt: new Date().toISOString(),
      dataQuality: {
        eventCount: 0,
        completeness: 0,
        hasGaps: true,
      },
    },
    failurePatterns: [],
    successPatterns: [],
    surpriseEvents: [],
    recommendations: [
      {
        recommendationId: "fallback-001",
        type: "caution",
        description: "Neuro-memory unavailable - using conservative template-based proposals",
        rationale: reason,
        basedOn: [],
        confidence: 1.0,
        priority: "high",
      },
    ],
  };
}

/**
 * Health check - verify neuro-memory is responding
 */
async healthCheck(): Promise<{ healthy: boolean; lastResponse: number; queueDepth: number }> {
  const stats = this.getBatchStats();
  const lastResponse = Date.now(); // TODO: Track actual last response time

  return {
    healthy: this.isRunning(),
    lastResponse,
    queueDepth: stats?.queueDepth ?? 0,
  };
}

