  /**
   * Generate proposals based on behavior analysis AND neuro-memory insights
   */
  private async generateProposals(analysis: BehaviorAnalysis): Promise<CodeChange[]> {
    console.log('[Evolution] Generating proposals...');

    // 🧠 NEW: Query neuro-memory for insights
    let neuroInsights: NeuroMemoryInsights | null = null;
    const neuroMemoryStart = Date.now();

    try {
      const bridge = getNeuroMemoryBridge();
      if (bridge && bridge.isRunning()) {
        console.log('[Evolution] Querying neuro-memory for insights...');
        neuroInsights = await bridge.queryInsights({
          types: ['failures', 'successes', 'recommendations'],
          minConfidence: 0.70,
          limit: 10,
        });

        const duration = Date.now() - neuroMemoryStart;
        console.log(
          `[Evolution] Neuro-memory insights retrieved in ${duration}ms: ` +
          `${neuroInsights.failurePatterns.length} failures, ` +
          `${neuroInsights.successPatterns.length} successes, ` +
          `${neuroInsights.recommendations.length} recommendations`
        );
      } else {
        console.log('[Evolution] Neuro-memory not available, using analysis-only proposals');
      }
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      console.warn(`[Evolution] Neuro-memory query failed: ${msg}`);
    }

    const proposals: CodeChange[] = [];

    // 1. Exec retry loops
    for (const retry of analysis.tool_retries) {
      if (retry.tool === 'exec' && retry.max_consecutive > 3) {
        const proposal = await this.generateExecRetryLimit(retry);
        if (proposal) proposals.push(proposal);
      }
    }

    // 2. Repeated errors - generate error handling improvements
    for (const error of analysis.errors) {
      if (error.count > 5) {
        const proposal = await this.generateErrorHandling(error);
        if (proposal) proposals.push(proposal);
      }
    }

    // 3. Heavy sessions - generate compaction improvements
    if (analysis.session_health.heavy_sessions > 3) {
      const proposal = await this.generateHeavySessionFix(analysis);
      if (proposal) proposals.push(proposal);
    }

    // 🧠 NEW: Generate proposals based on neuro-memory recommendations
    if (neuroInsights && neuroInsights.recommendations.length > 0) {
      const neuroProposals = await this.generateNeuroMemoryProposals(neuroInsights);
      proposals.push(...neuroProposals);
    }


    // 🧠 NEW: Tag proposals with memory-informed flag for metrics
    proposals.forEach(p => {
      (p as any).memory_informed = !neuroInsights; // Fallback mode if no neuro-memory
    });


    console.log(`[Evolution] Generated ${proposals.length} proposals total`);
    return proposals;
  }


  /**
   * NEW: Generate proposals from neuro-memory recommendations
   */
  private async generateNeuroMemoryProposals(insights: NeuroMemoryInsights): Promise<CodeChange[]> {
    const proposals: CodeChange[] = [];

    for (const rec of insights.recommendations) {
      // Only process high-confidence recommendations
      if (rec.confidence < 0.80) continue;

      // Skip low-priority unless they's critical issues
      if (rec.priority === 'low' && insights.failurePatterns.filter(f => f.severity === 'critical').length === 0) {
        continue;
      }

      // Generate different proposal types based on recommendation type
      switch (rec.type) {
        case 'avoid':
          // Generate constraint-based proposal
          const proposal = await this.generateAvoidanceProposal(rec, insights);
          if (proposal) proposals.push(proposal);
          break;

        case 'prefer':
          // Generate optimization proposal
          const proposal = await this.generatePreferProposal(rec, insights);
          if (proposal) proposals.push(proposal);
          break;

        case 'optimize':
          // Generate performance improvement proposal
          const proposal = await this.generateOptimizeProposal(rec, insights);
          if (proposal) proposals.push(proposal);
          break;

        case 'investigate':
          // Investigation requests don't generate code changes,
          // but we log them for manual review
          console.log(`[Evolution] Investigation needed: ${rec.description}`);
          break;

        case 'caution':
          // Generate safety check proposal
          const proposal = await this.generateCautionProposal(rec, insights);
          if (proposal) proposals.push(proposal);
          break;
      }
    }

    return proposals;
  }

  /**
   * Generate proposal to avoid a known failure pattern
   */
  private async generateAvoidanceProposal(
    rec: Recommendation,
    insights: NeuroMemoryInsights
  ): Promise<CodeChange | null> {
    // Find the failure pattern this recommendation is based on
    const relatedFailure = insights.failurePatterns.find(
      f => rec.basedOn.includes(f.patternId)
    );

    if (!relatedFailure) {
      console.warn(`[Evolution] Recommendation ${rec.recommendationId} has no matching failure pattern`);
      return null;
    }

    // Generate a guard/wrapper to avoid this failure
    return {
      id: randomUUID(),
      type: 'refactor',
      scope: 'safety',
      description: `Add safeguards to prevent ${relatedFailure.category}`,
      rationale: rec.rationale,
      target_files: this.identifyAffectedFiles(relatedFailure),
      patches: [{
        path: '',
        content: this.generateGuardCode(relatedFailure, rec)
      }],
      memory_informed: true,
      confidence: rec.confidence * 0.9, // Scale by recommendation confidence
      metadata: {
        based_on: rec.basedOn,
        failure_category: relatedFailure.category,
        failure_frequency: relatedFailure.frequency,
      }
    };
  }

  /**
   * Generate proposal to reinforce successful patterns
   */
  private async generatePreferProposal(
    rec: Recommendation,
    insights: NeuroMemoryInsights
  ): Promise<CodeChange | null> {
    // Find the success pattern this recommendation is based on
    const relatedSuccess = insights.successPatterns.find(
      f => rec.basedOn.includes(f.patternId)
    );

    if (!relatedSuccess) {
      console.warn(`[Evolution] Recommendation ${rec.recommendationId} has no matching success pattern`);
      return null;
    }

    // Generate a code change to replicate this success pattern
    return {
      id: randomUUID(),
      type: 'feature',
      scope: 'enhancement',
      description: `Replicate successful pattern: ${relatedSuccess.description}`,
      rationale: rec.rationale,
      target_files: this.identifyTargetFiles(relatedSuccess),
      patches: [{
        path: '',
        content: this.generateSuccessReplicationCode(relatedSuccess, rec)
      }],
      memory_informed: true,
      confidence: rec.confidence * 0.9,
