#!/usr/bin/env python3
"""
MCP Server for Neuro-Memory-Agent
Exposes memory operations as MCP tools
"""

import json
import sys
from datetime import datetime
from typing import Any, Dict, List, Optional, TYPE_CHECKING

# Print startup message immediately before heavy imports
print("Neuro-Memory MCP Server started", file=sys.stderr)
sys.stderr.flush()

# Lazy import components
_deferred_import_error = None

def _load_components():
    """Lazy load heavy components on first use"""
    global _deferred_import_error
    if _deferred_import_error is not None:
        raise _deferred_import_error

    try:
        from src.surprise import BayesianSurpriseEngine, SurpriseConfig
        from src.segmentation import EventSegmenter, SegmentationConfig
        from src.memory import EpisodicMemoryStore, EpisodicMemoryConfig
        from src.retrieval import TwoStageRetriever, RetrievalConfig
        from src.consolidation import MemoryConsolidationEngine, ConsolidationConfig
        import numpy as np

        # Use LM Studio for embeddings via OpenAI-compatible API
        import requests
        EMBEDDING_MODEL = "lmstudio"  # marker to use LM Studio API
        EMBEDDING_DIM = 768  # nomic-embed-text-v1.5 dimension
        LM_STUDIO_URL = "http://127.0.0.1:1234/v1/embeddings"
        LM_STUDIO_MODEL = "text-embedding-nomic-embed-text-v1.5"
        print("Using LM Studio embeddings (nomic-embed-text-v1.5)", file=sys.stderr)

        return {
            'BayesianSurpriseEngine': BayesianSurpriseEngine,
            'EventSegmenter': EventSegmenter,
            'EpisodicMemoryStore': EpisodicMemoryStore,
            'EpisodicMemoryConfig': EpisodicMemoryConfig,
            'TwoStageRetriever': TwoStageRetriever,
            'MemoryConsolidationEngine': MemoryConsolidationEngine,
            'np': np,
            'requests': requests,
            'EMBEDDING_MODEL': EMBEDDING_MODEL,
            'EMBEDDING_DIM': EMBEDDING_DIM,
            'LM_STUDIO_URL': LM_STUDIO_URL,
            'LM_STUDIO_MODEL': LM_STUDIO_MODEL
        }
    except Exception as e:
        _deferred_import_error = e
        raise


class NeuroMemoryMCP:
    """MCP Server for Neuro-Memory-Agent"""

    def __init__(self, input_dim: int = None):
        components = _load_components()
        self.input_dim = input_dim or components['EMBEDDING_DIM']
        self._components = components

        # Initialize components
        self.surprise_engine = components['BayesianSurpriseEngine'](self.input_dim)
        self.segmenter = components['EventSegmenter']()
        self.memory = components['EpisodicMemoryStore'](
            components['EpisodicMemoryConfig'](max_episodes=10000, embedding_dim=self.input_dim)
        )
        self.retriever = components['TwoStageRetriever'](self.memory)
        self.consolidation = components['MemoryConsolidationEngine']()

    def _get_embedding(self, content: str, provided_embedding: Optional[List[float]] = None):
        """Get embedding for content, using provided or generating new"""
        if provided_embedding is not None:
            return self._components['np'].array(provided_embedding)

        if self._components['EMBEDDING_MODEL'] == "lmstudio":
            # Use LM Studio API for embeddings
            try:
                response = self._components['requests'].post(
                    self._components['LM_STUDIO_URL'],
                    json={"input": content, "model": self._components['LM_STUDIO_MODEL']},
                    headers={"Authorization": "Bearer lm-studio"},
                    timeout=10
                )
                if response.status_code == 200:
                    data = response.json()
                    return self._components['np'].array(data['data'][0]['embedding'])
                else:
                    print(f"LM Studio embedding failed: {response.status_code}", file=sys.stderr)
                    return self._hash_embedding(content)
            except Exception as e:
                print(f"LM Studio embedding error: {e}, falling back to hash", file=sys.stderr)
                return self._hash_embedding(content)
        elif self._components['EMBEDDING_MODEL'] is not None:
            # Use sentence-transformers
            return self._components['EMBEDDING_MODEL'].encode([content])[0]
        else:
            # Fallback: simple hash-based embedding
            return self._hash_embedding(content)

    def _hash_embedding(self, text: str):
        """Simple hash-based embedding (fallback)"""
        embedding = self._components['np'].zeros(self.input_dim)
        for i, char in enumerate(text):
            idx = (ord(char) * (i + 1)) % self.input_dim
            embedding[idx] += self._components['np'].sin(ord(char) * 0.1) * 0.5
        # Normalize
        norm = self._components['np'].linalg.norm(embedding)
        return embedding / (norm or 1)

    def store_memory(self, content: str, embedding: List[float] = None, metadata: Dict = None) -> Dict:
        """Store a new memory episode (embedding optional, auto-generated if not provided)"""
        embedding_array = self._get_embedding(content, embedding)

        # Compute surprise
        surprise_info = self.surprise_engine.compute_surprise(embedding_array)

        # Store if novel
        if surprise_info['is_novel']:
            episode = self.memory.store_episode(
                content={"text": content, "metadata": metadata or {}},
                embedding=embedding_array,
                surprise=surprise_info['surprise'],
                timestamp=datetime.now()
            )
            # Extract episode_id from the returned Episode object
            episode_id = episode.episode_id if hasattr(episode, 'episode_id') else str(id(episode))
            return {
                "stored": True,
                "episode_id": episode_id,
                "surprise": surprise_info['surprise'],
                "is_novel": True
            }
        else:
            return {
                "stored": False,
                "surprise": surprise_info['surprise'],
                "is_novel": False,
                "reason": "Not surprising enough"
            }

    def retrieve_memories(self, query: str = None, query_embedding: List[float] = None, k: int = 5) -> List[Dict]:
        """Retrieve relevant memories (query text or embedding, one required)"""
        if query_embedding is not None:
            query_array = self._components['np'].array(query_embedding)
        elif query is not None:
            query_array = self._get_embedding(query)
        else:
            return {"error": "Either query or query_embedding required"}

        # retrieve() doesn't take k parameter - slice results after retrieval
        episodes = self.retriever.retrieve(
            query=query_array
        )

        # Convert episodes to JSON-serializable format and limit to k
        result = []
        for ep_tuple in episodes[:k]:
            # Handle tuple format (episode, score)
            if isinstance(ep_tuple, tuple):
                ep, score = ep_tuple
            else:
                ep = ep_tuple
                score = 0.0

            # Convert episode to dict
            if hasattr(ep, 'to_dict'):
                ep_dict = ep.to_dict()
            elif isinstance(ep, dict):
                ep_dict = ep
            else:
                ep_dict = {"content": str(ep)}

            result.append({
                "content": ep_dict.get("content", str(ep_dict)),
                "surprise": float(ep_dict.get("surprise", 0)),
                "timestamp": ep_dict.get("timestamp", datetime.now()).isoformat() if hasattr(ep_dict.get("timestamp", datetime.now()), 'isoformat') else str(ep_dict.get("timestamp", "")),
                "similarity": float(score)
            })

        return result

    def consolidate_memories(self) -> Dict:
        """Run memory consolidation"""
        stats = self.consolidation.consolidate(self.memory.episodes)
        schemas = self.consolidation.get_schema_summary()

        return {
            "replay_count": stats['replay_count'],
            "schemas_extracted": len(schemas),
            "schemas": schemas[:5]  # Top 5 schemas
        }

    def get_stats(self) -> Dict:
        """Get memory system statistics"""
        return {
            "total_episodes": len(self.memory.episodes),
            "mean_surprise": float(self.surprise_engine.mean_surprise),
            "std_surprise": float(self.surprise_engine.std_surprise),
            "observation_count": self.surprise_engine.step_count
        }

    def query_insights(self, query_type: str = "all", time_range: Dict = None, limit: int = 10) -> Dict:
        """
        Query neuro-memory for insights to inform evolution proposals.

        Args:
            query_type: Type of insights to query ("failure_patterns", "success_patterns", 
                       "surprise_events", "recommendations", "all")
            time_range: Optional dict with "start" and "end" ISO timestamps
            limit: Max number of items to return per category

        Returns:
            Dict with failure_patterns, success_patterns, surprise_events, recommendations
        """
        insights = {
            "failure_patterns": [],
            "success_patterns": [],
            "surprise_events": [],
            "recommendations": [],
            "metadata": {
                "query_type": query_type,
                "total_memories": len(self.memory.episodes),
                "time_range": time_range
            }
        }

        # Get all episodes sorted by surprise (highest first)
        episodes_with_surprise = []
        for ep in self.memory.episodes:
            surprise = getattr(ep, 'surprise', 0) if hasattr(ep, 'surprise') else 0
            episodes_with_surprise.append((ep, surprise))

        episodes_with_surprise.sort(key=lambda x: x[1], reverse=True)

        # Extract failure patterns (memories with failure/error metadata)
        if query_type in ["failure_patterns", "all"]:
            for ep, surprise in episodes_with_surprise[:limit]:
                content = getattr(ep, 'content', {}) if hasattr(ep, 'content') else {}
                if isinstance(content, dict):
                    metadata = content.get("metadata", {})
                    if metadata.get("type") in ["error", "failure", "bug", "issue"]:
                        insights["failure_patterns"].append({
                            "content": content.get("text", str(content)),
                            "surprise": float(surprise),
                            "metadata": metadata,
                            "confidence": min(1.0, surprise / 2.0)  # Higher surprise = higher confidence
                        })

        # Extract success patterns (memories with success/completion metadata)
        if query_type in ["success_patterns", "all"]:
            for ep, surprise in episodes_with_surprise[:limit]:
                content = getattr(ep, 'content', {}) if hasattr(ep, 'content') else {}
                if isinstance(content, dict):
                    metadata = content.get("metadata", {})
                    if metadata.get("type") in ["success", "completion", "fix", "improvement"]:
                        insights["success_patterns"].append({
                            "content": content.get("text", str(content)),
                            "surprise": float(surprise),
                            "metadata": metadata,
                            "confidence": min(1.0, surprise / 2.0)
                        })

        # Extract high-surprise events (potential anomalies or significant changes)
        if query_type in ["surprise_events", "all"]:
            mean_surprise = float(self.surprise_engine.mean_surprise)
            std_surprise = float(self.surprise_engine.std_surprise)
            threshold = mean_surprise + (2 * std_surprise)  # 2 standard deviations

            for ep, surprise in episodes_with_surprise[:limit]:
                if surprise > threshold:
                    content = getattr(ep, 'content', {}) if hasattr(ep, 'content') else {}
                    insights["surprise_events"].append({
                        "content": content.get("text", str(content)) if isinstance(content, dict) else str(content),
                        "surprise": float(surprise),
                        "threshold": float(threshold),
                        "significance": "high" if surprise > threshold * 1.5 else "moderate"
                    })

        # Generate recommendations based on patterns
        if query_type in ["recommendations", "all"]:
            # Analyze failure patterns for recommendations
            failure_count = len(insights["failure_patterns"])
            if failure_count > 5:
                insights["recommendations"].append({
                    "type": "stability",
                    "priority": "high",
                    "suggestion": f"High failure pattern count ({failure_count}). Consider stability improvements before new features.",
                    "confidence": 0.8
                })

            # High surprise indicates potential issues or opportunities
            if len(insights["surprise_events"]) > 3:
                insights["recommendations"].append({
                    "type": "investigation",
                    "priority": "medium",
                    "suggestion": "Multiple high-surprise events detected. Investigate anomalies before proceeding.",
                    "confidence": 0.7
                })

            # Success patterns indicate good practices
            success_count = len(insights["success_patterns"])
            if success_count > 3:
                insights["recommendations"].append({
                    "type": "leverage",
                    "priority": "low",
                    "suggestion": "Strong success patterns found. Consider applying similar approaches to other areas.",
                    "confidence": 0.75
                })

        return insights

    def batch_store_memory(self, items: List[Dict]) -> List[Dict]:
        """
        Store multiple memories in a single batch call.

        Args:
            items: List of dicts with keys: id, content, embedding (optional), metadata (optional)

        Returns:
            List of results, each with: id, result (stored, episode_id, surprise, is_novel, reason), error (optional)
        """
        results = []

        for item in items:
            item_id = item.get("id")
            try:
                # Get embedding - use provided or generate
                embedding_array = self._get_embedding(
                    item.get("content", ""),
                    item.get("embedding")
                )

                # Compute surprise
                surprise_info = self.surprise_engine.compute_surprise(embedding_array)

                # Store if novel
                if surprise_info['is_novel']:
                    episode = self.memory.store_episode(
                        content={"text": item.get("content", ""), "metadata": item.get("metadata", {})},
                        embedding=embedding_array,
                        surprise=surprise_info['surprise'],
                        timestamp=datetime.now()
                    )
                    episode_id = episode.episode_id if hasattr(episode, 'episode_id') else str(id(episode))
                    results.append({
                        "id": item_id,
                        "result": {
                            "stored": True,
                            "episode_id": episode_id,
                            "surprise": float(surprise_info['surprise']),
                            "is_novel": True
                        }
                    })
                else:
                    results.append({
                        "id": item_id,
                        "result": {
                            "stored": False,
                            "surprise": float(surprise_info['surprise']),
                            "is_novel": False,
                            "reason": "Not surprising enough"
                        }
                    })
            except Exception as e:
                results.append({
                    "id": item_id,
                    "error": str(e)
                })

        return results


def handle_request(request: Dict) -> Dict:
    """Handle MCP tool request"""

    # Global instance (in real MCP, this would be session-based)
    if not hasattr(handle_request, 'instance'):
        handle_request.instance = NeuroMemoryMCP()

    mcp = handle_request.instance
    request_id = request.get('id')  # Extract id for response
    method = request.get('method')
    params = request.get('params', {})

    try:
        if method == 'store_memory':
            result = mcp.store_memory(
                content=params['content'],
                embedding=params.get('embedding'),  # Optional now
                metadata=params.get('metadata')
            )
        elif method == 'batch_store_memory':
            result = mcp.batch_store_memory(
                items=params.get('items', [])
            )
        elif method == 'retrieve_memories':
            result = mcp.retrieve_memories(
                query=params.get('query'),  # Can use text now
                query_embedding=params.get('embedding'),
                k=params.get('k', 5)
            )
        elif method == 'consolidate_memories':
            result = mcp.consolidate_memories()
        elif method == 'get_stats':
            result = mcp.get_stats()
        elif method == 'query_insights':
            result = mcp.query_insights(
                query_type=params.get('query_type', 'all'),
                time_range=params.get('time_range'),
                limit=params.get('limit', 10)
            )
        else:
            return {"id": request_id, "error": f"Unknown method: {method}"}

        return {"id": request_id, "result": result}

    except Exception as e:
        return {"id": request_id, "error": str(e)}


def main():
    """MCP Server main loop"""
    # Startup message already printed at module load

    for line in sys.stdin:
        try:
            request = json.loads(line)
            response = handle_request(request)
            print(json.dumps(response))
            sys.stdout.flush()
        except json.JSONDecodeError as e:
            # Can't include id if we couldn't parse the request
            print(json.dumps({"id": None, "error": f"Invalid JSON: {e}"}))
            sys.stdout.flush()
        except Exception as e:
            # Try to include id from request if available
            try:
                request = json.loads(line)
                request_id = request.get('id')
            except:
                request_id = None
            print(json.dumps({"id": request_id, "error": str(e)}))
            sys.stdout.flush()


if __name__ == "__main__":
    main()

/**
 * Neuro-Memory-Agent Bridge
 *
 * Connects OpenClaw's event mesh to the neuro-memory-agent Python system
 * for episodic memory with Bayesian surprise detection, consolidation, and retrieval.
 */

import { spawn, ChildProcess } from "node:child_process";
import { createSubsystemLogger } from "../logging/subsystem.js";
import { isVerbose } from "../globals.js";
import {
  MemoryBatchQueue,
  type BatchMemoryItem,
  type BatchStoreResult,
} from "./memory-batch-queue.js";

const log = createSubsystemLogger("neuro-memory");

export type NeuroMemoryConfig = {
  pythonPath?: string;
  agentPath: string;
  inputDim?: number;
  autoConsolidate?: boolean;
  consolidateIntervalMs?: number;
  // Batching configuration
  enableBatching?: boolean;
  batchConfig?: {
    batchSize?: number; // default: 10
    flushInterval?: number; // default: 2000ms
    maxQueueSize?: number; // default: 100
  };
};

export type Episode = {
  id: string;
  content: {
    text: string;
    metadata: Record<string, unknown>;
  };
  surprise: number;
  timestamp: string;
  similarity?: number;
};

export type StoreResult = {
  stored: boolean;
  episode_id?: string;
  surprise: number;
  is_novel: boolean;
  reason?: string;
};

export type ConsolidationResult = {
  replay_count: number;
  schemas_extracted: number;
  schemas: string[];
};

export type MemoryStats = {
  total_episodes: number;
  mean_surprise: number;
  std_surprise: number;
  observation_count: number;
};

/**
 * Neuro-Memory-Agent Bridge
 *
 * Uses MCP protocol over stdio to communicate with Python memory system
 */
export class NeuroMemoryBridge {
  private process: ChildProcess | null = null;
  private config: NeuroMemoryConfig;
  private requestCallbacks: Map<string, { resolve: Function; reject: Function }> = new Map();
  private requestId = 0;
  private buffer = "";
  private isReady = false;
  private consolidateTimer?: ReturnType<typeof setInterval>;
  private memoryBatch?: MemoryBatchQueue;

  constructor(config: NeuroMemoryConfig) {
    this.config = {
      pythonPath: config.pythonPath || "python3",
      inputDim: config.inputDim || 768,
      autoConsolidate: config.autoConsolidate ?? true,
      consolidateIntervalMs: config.consolidateIntervalMs || 3600000, // 1 hour
      enableBatching: config.enableBatching ?? true,
      batchConfig: {
        batchSize: config.batchConfig?.batchSize ?? 10,
        flushInterval: config.batchConfig?.flushInterval ?? 2000,
        maxQueueSize: config.batchConfig?.maxQueueSize ?? 100,
        ...config.batchConfig,
      },
      ...config,
    };
  }

  /**
   * Start the neuro-memory-agent MCP server
   */
  async start(): Promise<void> {
    return new Promise((resolve, reject) => {
      log.info(`Starting neuro-memory-agent from ${this.config.agentPath}`);

      this.process = spawn(this.config.pythonPath!, [`${this.config.agentPath}/mcp_server.py`], {
        cwd: this.config.agentPath,
        stdio: ["pipe", "pipe", "pipe"],
      });

      this.process.stderr?.on("data", (data) => {
        const msg = data.toString().trim();
        if (msg.includes("MCP Server started")) {
          this.isReady = true;

          // Initialize batch queue if enabled
          if (this.config.enableBatching) {
            this.initBatchQueue();
          }

          log.info("✅ Neuro-memory-agent MCP server ready");

          // Start auto-consolidation if enabled
          if (this.config.autoConsolidate) {
            this.startAutoConsolidation();
          }

          resolve();
        } else {
          log.debug("[neuro-memory stderr]", msg);
        }
      });

      this.process.stdout?.on("data", (data) => {
        this.buffer += data.toString();
        this.processBuffer();
      });

      this.process.on("error", (error) => {
        log.error("Neuro-memory-agent process error:", error);
        this.isReady = false;
        reject(error);
      });

      this.process.on("exit", (code) => {
        if (isVerbose()) {
          log.warn(`Neuro-memory-agent exited with code ${code}`);
        }
        this.isReady = false;
      });

      // Timeout if server doesn't start
      setTimeout(() => {
        if (!this.isReady) {
          reject(new Error("Neuro-memory-agent startup timeout"));
        }
      }, 10000);
    });
  }

  /**
   * Stop the neuro-memory-agent MCP server
   */
  async stop(): Promise<void> {
    // Flush remaining memories before shutdown
    if (this.memoryBatch) {
      log.info("Flushing remaining memory batch...");
      await this.memoryBatch.shutdown();
    }

    if (this.consolidateTimer) {
      clearInterval(this.consolidateTimer);
    }

    if (this.process) {
      return new Promise((resolve) => {
        this.process!.on("exit", () => {
          log.info("Neuro-memory-agent stopped");
          resolve();
        });
        this.process!.kill("SIGTERM");

        // Force kill after 5s
        setTimeout(() => {
          if (this.process) {
            this.process.kill("SIGKILL");
          }
        }, 5000);
      });
    }
  }

  /**
   * Initialize batch queue
   */
  private initBatchQueue(): void {
    this.memoryBatch = new MemoryBatchQueue({
      batchSize: this.config.batchConfig!.batchSize,
      flushInterval: this.config.batchConfig!.flushInterval,
      maxQueueSize: this.config.batchConfig!.maxQueueSize,
      onFlush: async (items: BatchMemoryItem[]): Promise<BatchStoreResult[]> => {
        return this.batchStoreInternal(items);
      },
    });

    log.info(
      `Memory batching enabled (batch: ${this.config.batchConfig!.batchSize}, ` +
        `interval: ${this.config.batchConfig!.flushInterval}ms)`,
    );
  }

  /**
   * Store a memory episode (embedding auto-generated in Python)
   */
  async storeMemory(content: string, metadata?: Record<string, unknown>): Promise<StoreResult> {
    this.ensureReady();

    // Use batching if enabled
    if (this.memoryBatch) {
      const result = await this.memoryBatch.push({ content, metadata });
      return {
        stored: result.stored,
        episode_id: result.episode_id,
        surprise: result.surprise,
        is_novel: result.is_novel,
        reason: result.reason,
      };
    }

    // Fallback to direct call
    return this.request("store_memory", { content, metadata });
  }

  /**
   * Store a memory episode with provided embedding
   */
  async storeMemoryWithEmbedding(
    content: string,
    embedding: number[],
    metadata?: Record<string, unknown>,
  ): Promise<StoreResult> {
    this.ensureReady();

    // Use batching if enabled
    if (this.memoryBatch) {
      const result = await this.memoryBatch.push({ content, embedding, metadata });
      return {
        stored: result.stored,
        episode_id: result.episode_id,
        surprise: result.surprise,
        is_novel: result.is_novel,
        reason: result.reason,
      };
    }

    // Fallback to direct call
    return this.request("store_memory", { content, embedding, metadata });
  }

  /**
   * Retrieve relevant memories (using text query)
   */
  async retrieveMemories(query: string, k: number = 5): Promise<Episode[]> {
    this.ensureReady();
    return this.request("retrieve_memories", { query, k });
  }

  /**
   * Retrieve relevant memories (using embedding)
   */
  async retrieveMemoriesByEmbedding(queryEmbedding: number[], k: number = 5): Promise<Episode[]> {
    this.ensureReady();
    return this.request("retrieve_memories", { embedding: queryEmbedding, k });
  }

  /**
   * Run memory consolidation (sleep-like replay)
   */
  async consolidateMemories(): Promise<ConsolidationResult> {
    this.ensureReady();
    return this.request("consolidate_memories", {});
  }

  /**
   * Get memory system statistics
   */
  async getStats(): Promise<MemoryStats> {
    this.ensureReady();
    return this.request("get_stats", {});
  }

  /**
   * Check if bridge is ready
   */
  isRunning(): boolean {
    return this.isReady && this.process !== null;
  }

  /**
   * Force flush batch queue
   */
  async flushBatch(): Promise<void> {
    if (this.memoryBatch) {
      await this.memoryBatch.flush();
    }
  }

  /**
   * Get batch statistics
   */
  getBatchStats() {
    return this.memoryBatch?.getStats() ?? null;
  }

  /**
   * Query neuro-memory for evolution insights
   * This is the PRIMARY method called by evolution service
   * 
   * Returns insights about failures, successes, surprises, and recommendations
   * for smarter proposal generation.
   */
  async queryInsights(query?: import("../types/neuro-memory-insights.js").EvolutionQuery): Promise<import("../types/neuro-memory-insights.js").NeuroMemoryInsights> {
    this.ensureReady();

    const startTime = Date.now();
    log.debug("[Evolution] Querying neuro-memory for insights...");

    try {
      const result = await this.request("query_insights", query || {});

      const duration = Date.now() - startTime;
      log.info(
        `[Evolution] Retrieved insights in ${duration}ms: ` +
        `${result.failurePatterns?.length || 0} failures, ` +
        `${result.successPatterns?.length || 0} successes, ` +
        `${result.recommendations?.length || 0} recommendations`
      );

      return result;
    } catch (error) {
      const msg = error instanceof Error ? error.message : String(error);
      log.error(`[Evolution] Failed to query insights: ${msg}`);

      // Return fallback insights (will trigger template-based evolution)
      return this.getFallbackInsights(msg);
    }
  }

  /**
   * Get fallback insights when neuro-memory is unavailable
   * This ensures evolution can still run with template-based proposals
   */
  private getFallbackInsights(reason: string): import("../types/neuro-memory-insights.js").NeuroMemoryInsights {
    log.warn(`[Evolution] Using fallback insights (reason: ${reason})`);

    return {
      metadata: {
        period: {
          start: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
          end: new Date().toISOString().split('T')[0],
        },
        generatedAt: new Date().toISOString(),
        dataQuality: {
          eventCount: 0,
          completeness: 0,
          hasGaps: true,
        },
      },
      failurePatterns: [],
      successPatterns: [],
      surpriseEvents: [],
      recommendations: [
        {
          recommendationId: "fallback-001",
          type: "caution",
          description: "Neuro-memory unavailable - using conservative template-based proposals",
          rationale: reason,
          basedOn: [],
          confidence: 1.0,
          priority: "high",
        },
      ],
    };
  }

  /**
   * Health check - verify neuro-memory is responding
   */
  async healthCheck(): Promise<{ healthy: boolean; lastResponse: number; queueDepth: number }> {
    const stats = this.getBatchStats();
    const lastResponse = Date.now(); // TODO: Track actual last response time

    return {
      healthy: this.isRunning(),
      lastResponse,
      queueDepth: stats?.queueDepth ?? 0,
    };
  }

  // Method-specific timeouts (in milliseconds)
  private static readonly METHOD_TIMEOUTS: Record<string, number> = {
    consolidate_memories: 600000, // 10 minutes for heavy consolidation work
    store_memory: 60000, // 1 minute for storing (includes embedding generation)
    retrieve_memories: 30000, // 30 seconds for retrieval
    get_stats: 10000, // 10 seconds for stats
  };

  private static readonly DEFAULT_TIMEOUT = 30000; // 30 seconds default

  /**
   * Internal batch store - sends to Python
   */
  private async batchStoreInternal(items: BatchMemoryItem[]): Promise<BatchStoreResult[]> {
    return new Promise((resolve, reject) => {
      const id = String(++this.requestId);

      this.requestCallbacks.set(id, {
        resolve: (results: BatchStoreResult[]) => {
          resolve(results);
        },
        reject: (error: Error) => {
          reject(error);
        },
      });

      const request =
        JSON.stringify({
          id,
          method: "batch_store_memory",
          params: {
            items: items.map((item) => ({
              id: item.id,
              content: item.content,
              embedding: item.embedding,
              metadata: item.metadata,
            })),
          },
        }) + "\n";
      log.debug(`[MCP→] Sending batch request ${id}: ${items.length} items`);
      this.process?.stdin?.write(request);

      // Extended timeout for batch operations
      const timeout = 120000; // 2 minutes for batches
      setTimeout(() => {
        if (this.requestCallbacks.has(id)) {
          this.requestCallbacks.delete(id);
          log.debug(`[MCP✗] Batch request ${id} timed out after ${timeout / 1000}s`);
          reject(new Error(`Batch store timeout after ${timeout / 1000}s`));
        }
      }, timeout);
    });
  }

  /**
   * Send request to MCP server
   */
  private async request<T>(method: string, params: Record<string, unknown>): Promise<T> {
    return new Promise((resolve, reject) => {
      const id = String(++this.requestId);

      this.requestCallbacks.set(id, { resolve, reject });

      const request = JSON.stringify({ id, method, params }) + "\n";
      log.debug(`[MCP→] Sending request ${id}: ${method}`);
      this.process?.stdin?.write(request);

      // Use method-specific timeout
      const timeout =
        NeuroMemoryBridge.METHOD_TIMEOUTS[method] ?? NeuroMemoryBridge.DEFAULT_TIMEOUT;
      setTimeout(() => {
        if (this.requestCallbacks.has(id)) {
          this.requestCallbacks.delete(id);
          log.debug(`[MCP✗] Request ${id} (${method}) timed out after ${timeout / 1000}s`);
          reject(new Error(`Request ${method} timeout after ${timeout / 1000}s`));
        }
      }, timeout);
    });
  }

  /**
   * Process stdout buffer for responses
   */
  private processBuffer(): void {
    const lines = this.buffer.split("\n");
    this.buffer = lines.pop() || "";

    for (const line of lines) {
      if (!line.trim()) continue;

      try {
        const response = JSON.parse(line);
        const callback = this.requestCallbacks.get(response.id);

        if (callback) {
          this.requestCallbacks.delete(response.id);
          log.debug(`[MCP←] Received response for ${response.id}`);

          if (response.error) {
            callback.reject(new Error(response.error));
          } else {
            // Handle both single result and batch result (array)
            callback.resolve(response.result);
          }
        } else {
          log.warn(`[MCP?] Received response with unknown id: ${response.id}`);
        }
      } catch (error) {
        log.warn("Failed to parse response:", line);
      }
    }
  }

  /**
   * Ensure bridge is ready
   */
  private ensureReady(): void {
    if (!this.isReady || !this.process) {
      throw new Error("Neuro-memory-agent not running. Call start() first.");
    }
  }

  /**
   * Start automatic consolidation timer
   */
  private startAutoConsolidation(): void {
    this.consolidateTimer = setInterval(async () => {
      try {
        const result = await this.consolidateMemories();
        log.info(
          `Memory consolidation complete: ${result.replay_count} replays, ${result.schemas_extracted} schemas`,
        );
      } catch (error) {
        const msg = error instanceof Error ? error.message : String(error);
        log.error(`Auto-consolidation failed: ${msg}`);

        // If consolidation times out repeatedly, it may indicate the agent is stuck
        // Log additional context for debugging
        if (msg.includes("timeout")) {
          log.warn(
            `Consolidation timeout detected. ` +
            `This may indicate: (1) large memory backlog, (2) agent process stuck, ` +
            `or (3) insufficient system resources. ` +
            `Next consolidation will retry in ${this.config.consolidateIntervalMs! / 60000} minutes.`,
          );
        }
      }
    }, this.config.consolidateIntervalMs!);

    log.info(
      `Auto-consolidation enabled (every ${this.config.consolidateIntervalMs! / 60000} minutes)`,
    );
  }
}

// Singleton with promise lock to prevent race conditions
let instance: NeuroMemoryBridge | null = null;
let initPromise: Promise<NeuroMemoryBridge> | null = null;

export function getNeuroMemoryBridge(): NeuroMemoryBridge | null {
  return instance;
}

export async function initNeuroMemoryBridge(
  agentPath: string = "/Users/tolga/Desktop/neuro-memory-agent",
): Promise<NeuroMemoryBridge> {
  // Return existing instance
  if (instance) {
    return instance;
  }

  // Wait for in-progress initialization (prevents race condition)
  if (initPromise) {
    return initPromise;
  }

  // Start initialization with lock
  initPromise = (async () => {
    const bridge = new NeuroMemoryBridge({ agentPath });
    await bridge.start();
    instance = bridge;
    return bridge;
  })();

  try {
    return await initPromise;
  } finally {
