// PERFORMANCE OPTIMIZATION: Base timeouts (will be multiplied by systemLoad)
private static readonly BASE_TIMEOUTS: Record<string, number> = {
  consolidate_memories: 300000, // Base: 5 minutes
  store_memory: 30000, // Base: 30 seconds
  retrieve_memories: 15000, // Base: 15 seconds
  get_stats: 5000, // Base: 5 seconds
  batch_store_memory: 60000, // Base: 1 minute
};

private static readonly DEFAULT_TIMEOUT = 30000; // 30 seconds default

/**
 * Get adaptive timeout based on method and system load
 */
private getAdaptiveTimeout(method: string): number {
  const baseTimeout = NeuroMemoryBridge.BASE_TIMEOUTS[method] ?? NeuroMemoryBridge.DEFAULT_TIMEOUT;

  // Get average response time for this method
  const times = this.responseTimes.get(method) || [];
  if (times.length === 0) {
    return baseTimeout * this.systemLoad;
  }

  // Calculate P95 response time
  const sorted = [...times].sort((a, b) => a - b);
  const p95Index = Math.floor(sorted.length * 0.95);
  const p95Time = sorted[p95Index];

  // Adaptive timeout = max(base * load, P95 * 2)
  const adaptiveTimeout = Math.max(
    baseTimeout * this.systemLoad,
    p95Time * 2
  );

  // Cap at 3x base timeout
  return Math.min(adaptiveTimeout, baseTimeout * 3);
}

/**
 * Record response time for adaptive timeout calculation
 */
private recordResponseTime(method: string, duration: number): void {
  if (!this.responseTimes.has(method)) {
    this.responseTimes.set(method, []);
  }

  const times = this.responseTimes.get(method)!;
  times.push(duration);

  // Keep last 100 samples
  if (times.length > 100) {
    times.shift();
  }

  // Update system load indicator
  this.updateSystemLoad();
}

/**
 * Update system load based on recent performance
 */
private updateSystemLoad(): void {
  const allTimes: number[] = [];
  for (const times of this.responseTimes.values()) {
    allTimes.push(...times);
  }

  if (allTimes.length < 10) {
    return; // Not enough data
  }

  // Calculate median response time
  const sorted = [...allTimes].sort((a, b) => a - b);
  const median = sorted[Math.floor(sorted.length / 2)];

  // Baseline: 1000ms median is normal load
  const baselineMedian = 1000;

  // Load factor: 1.0 at baseline, increases as median increases
  this.systemLoad = Math.max(0.5, Math.min(3.0, median / baselineMedian));

  log.debug(`System load updated: ${this.systemLoad.toFixed(2)}x (median: ${median}ms)`);
}

/**
 * Start health monitoring to detect stuck processes
 */
private startHealthMonitoring(): void {
  this.healthCheckInterval = setInterval(() => {
    const now = Date.now();
    const timeSinceLastResponse = now - this.lastHealthCheck;

    // If no responses for 5 minutes, increase load factor
    if (timeSinceLastResponse > 300000) {
      this.systemLoad = Math.min(3.0, this.systemLoad * 1.5);
      log.warn(
        `No responses for ${Math.floor(timeSinceLastResponse / 1000)}s, ` +
        `increasing timeout multiplier to ${this.systemLoad.toFixed(2)}x`
      );
    }
  }, 60000); // Check every minute
}

